    frequency_map = defaultdict(int)
    for num in nums:
        frequency_map[num] += 1

    # Initialize variables to track the current largest and second largest numbers
    current_max = 0
    current_second_max = float('-inf')

    # Iterate through the frequency map to find the second largest number
    for num, count in frequency_map.items():
        if count >= 2:
            if count > current_second_max:
                current_second_max = current_max
                current_max = num
            elif count > current_second_max:
                current_second_max = num

    # Return the second largest number or None if there are fewer than two distinct values
    return current_second_max if len(frequency_map) >= 2 else None

